/* kernel/bin/builtins.c — package registry
 *
 * "core" is always present. Optional packages are appended conditionally:
 * if KELPOS_PKG_<NAME> is defined (build/pkgconf.h, generated by the
 * Makefile from PKGS=...), the package's command table is linked in;
 * otherwise the entry is listed as "not built". */
#include <stddef.h>
#include <string.h>
#include "commands.h"

/* ── core ───────────────────────────────────────────────────────────── */

static const struct builtin core_cmds[] = {
    { "help",     cmd_help,     "list all commands" },
    { "echo",     cmd_echo,     "print arguments" },
    { "clear",    cmd_clear,    "clear the screen" },
    { "uptime",   cmd_uptime,   "time since boot" },
    { "pkg",      cmd_pkg,      "package manager (list/info/enable/disable)" },
    { "reboot",   cmd_reboot,   "reboot the machine" },
    { "shutdown", cmd_shutdown, "QEMU shutdown (halt on real hardware)" },
};

/* ── optional packages ──────────────────────────────────────────────── */

#ifdef KELPOS_PKG_ABOUT
extern const struct builtin about_cmds[];
#define ABOUT_TABLE about_cmds, 1, true
#else
#define ABOUT_TABLE 0, 0, false
#endif

#ifdef KELPOS_PKG_MEM
extern const struct builtin mem_cmds[];
#define MEM_TABLE mem_cmds, 1, true
#else
#define MEM_TABLE 0, 0, false
#endif

#ifdef KELPOS_PKG_CRC
extern const struct builtin crc_cmds[];
#define CRC_TABLE crc_cmds, 1, true
#else
#define CRC_TABLE 0, 0, false
#endif

#ifdef KELPOS_PKG_COWSAY
extern const struct builtin cowsay_cmds[];
#define COWSAY_TABLE cowsay_cmds, 1, true
#else
#define COWSAY_TABLE 0, 0, false
#endif

#ifdef KELPOS_PKG_FORTUNE
extern const struct builtin fortune_cmds[];
#define FORTUNE_TABLE fortune_cmds, 1, true
#else
#define FORTUNE_TABLE 0, 0, false
#endif

struct package packages[] = {
    { "core",     "essential commands (always present)", core_cmds, sizeof(core_cmds) / sizeof(core_cmds[0]), true, true },
    { "about",    "information about KelpOS",            ABOUT_TABLE,    true },
    { "mem",      "heap usage statistics",               MEM_TABLE,      true },
    { "crc",      "CRC32 checksum demo (C/Rust)",        CRC_TABLE,      true },
    { "cowsay",   "a cow says whatever you want",        COWSAY_TABLE,   true },
    { "fortune",  "random quotes about free software",   FORTUNE_TABLE,  true },
};

const size_t package_count = sizeof(packages) / sizeof(packages[0]);

/* ── lookup helpers ─────────────────────────────────────────────────── */

struct package *pkg_find(const char *name)
{
    for (size_t i = 0; i < package_count; i++)
        if (strcmp(name, packages[i].name) == 0)
            return &packages[i];
    return 0;
}

const struct builtin *pkg_find_cmd(const char *name)
{
    for (size_t i = 0; i < package_count; i++) {
        const struct package *p = &packages[i];
        if (!p->compiled || !p->enabled)
            continue;
        for (size_t c = 0; c < p->cmd_count; c++)
            if (strcmp(name, p->cmds[c].name) == 0)
                return &p->cmds[c];
    }
    return 0;
}

bool pkg_set_enabled(const char *name, bool enabled)
{
    struct package *p = pkg_find(name);
    if (!p || !p->compiled)
        return false;
    p->enabled = enabled;
    return true;
}
